SELECT fn_cp_import_case('ordre-blocage-etudiant-etablissement', '{"slug": "ordre-blocage-etudiant-etablissement", "title": "Les poubelles bloquent l''entrée, la direction demande l''intervention", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 8 heures. Vous êtes appelée devant une université dont l''entrée principale a été bloquée par des poubelles disposées par un groupe d''étudiants mobilisés, la direction de cet établissement sollicitant directement votre intervention pour permettre la reprise normale de l''accès à ce site universitaire. Cette demande de réquisition par cette direction, dans un contexte où l''ensemble des personnes impliquées reste des jeunes majeurs et où cette situation bénéficie déjà d''une forte médiatisation, nécessite une vérification préalable du cadre exact dans lequel votre intervention est sollicitée avant d''agir.\n\nCette configuration, où la demande émane de la direction de cet établissement mais où votre intervention doit s''inscrire dans un cadre juridique précis qui reste à vérifier, impose une prudence méthodologique avant tout engagement sur ce site universitaire particulièrement sensible.\n\nCette situation nécessite de vérifier le cadre exact de cette intervention avant d''agir, cette rigueur préalable restant essentielle compte tenu de la sensibilité particulière de ce contexte universitaire fortement médiatisé.", "questions": [{"position": 1, "max_points": 5, "label": "Comment vérifiez-vous le cadre exact de cette intervention avant d''agir sur ce site universitaire ?", "hint": "Cette vérification préalable reste essentielle compte tenu du cadre juridique spécifique qui encadre l''intervention des forces de l''ordre sur ce type d''établissement.", "perfect": "Je vérifie précisément la nature et l''étendue de la demande formulée par cette direction, cette clarification étant nécessaire avant tout engagement sur ce site universitaire.\n\nJe reste attentive au cadre juridique spécifique qui peut encadrer l''intervention des forces de l''ordre au sein de ce type d''établissement, cette réalité institutionnelle méritant d''être clarifiée avant toute action.\n\nJe transmets cette sollicitation à ma hiérarchie pour validation du cadre approprié, cette remontée restant nécessaire compte tenu de la sensibilité particulière de ce contexte universitaire.\n\nJe reste attentive à ne pas agir précipitamment sur la seule demande de cette direction, cette prudence méthodologique restant essentielle avant toute intervention sur ce site sensible.", "points": [{"position": 1, "label": "Vérifier précisément la nature et l''étendue de la demande formulée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : clarification avant tout engagement.", "groups": [{"position": 1, "keywords": ["demande vérifiée", "nature précisée", "engagement clarifié"]}]}, {"position": 2, "label": "Rester attentive au cadre juridique spécifique de ce type d''établissement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réalité institutionnelle à clarifier avant toute action.", "groups": [{"position": 1, "keywords": ["cadre juridique spécifique", "établissement universitaire", "réalité institutionnelle"]}]}, {"position": 3, "label": "Transmettre cette sollicitation à la hiérarchie pour validation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Remontée nécessaire compte tenu de la sensibilité.", "groups": [{"position": 1, "keywords": ["sollicitation transmise", "validation hiérarchique", "sensibilité reconnue"]}]}, {"position": 4, "label": "Ne pas agir précipitamment sur la seule demande de la direction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prudence méthodologique avant toute intervention.", "groups": [{"position": 1, "keywords": ["pas de précipitation", "prudence méthodologique", "intervention réfléchie"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous la médiatisation forte de cette situation dans votre approche de cette intervention ?", "hint": "Cette médiatisation importante nécessite une attention particulière sur la manière dont cette intervention sera perçue et documentée par les observateurs extérieurs.", "perfect": "Je reste consciente de cette médiatisation forte, cette réalité m''incitant à une rigueur professionnelle renforcée dans l''ensemble de mon comportement sur ce site.\n\nJe reste attentive à ne pas réagir à d''éventuelles provocations ou captations qui pourraient survenir dans ce contexte médiatique particulièrement sensible.\n\nJe privilégie une approche mesurée qui tienne compte de cette exposition, cette prudence restant appropriée face à une situation qui pourrait être largement commentée par la suite.\n\nJe reste factuelle dans mes échanges avec l''ensemble des personnes présentes, cette rigueur restant essentielle compte tenu de cette attention médiatique particulière.", "points": [{"position": 1, "label": "Rester consciente de cette médiatisation forte", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : rigueur professionnelle renforcée.", "groups": [{"position": 1, "keywords": ["médiatisation consciente", "rigueur renforcée", "comportement irréprochable"]}]}, {"position": 2, "label": "Ne pas réagir à d''éventuelles provocations ou captations", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Prudence dans ce contexte médiatique sensible.", "groups": [{"position": 1, "keywords": ["pas de réaction", "provocations évitées", "contexte médiatique"]}]}, {"position": 3, "label": "Privilégier une approche mesurée face à cette exposition", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prudence face à une situation largement commentée.", "groups": [{"position": 1, "keywords": ["approche mesurée", "exposition prise en compte", "situation commentée"]}]}, {"position": 4, "label": "Rester factuelle dans les échanges avec les personnes présentes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur compte tenu de l''attention médiatique.", "groups": [{"position": 1, "keywords": ["échanges factuels", "rigueur maintenue", "attention médiatique"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous ces étudiants mobilisés en tenant compte de leur statut de jeunes majeurs ?", "hint": "Ces étudiants, bien que majeurs, restent dans une situation de mobilisation qui mérite un traitement mesuré et respectueux de leur expression revendicative légitime.", "perfect": "Je reste attentive à traiter ces étudiants avec le respect dû à toute personne, cette mobilisation relevant d''une expression revendicative qui reste légitime dans son principe.\n\nJe recherche un dialogue avec ces étudiants pour comprendre leurs revendications et envisager une résolution pacifique de ce blocage, cette approche restant préférable à une confrontation directe.\n\nJe reste factuelle sur les conséquences de ce blocage, notamment sur la nécessité de rétablir l''accès normal à cet établissement, sans pour autant dénigrer leur démarche revendicative.\n\nJe reste attentive à la proportionnalité de toute action envisagée, cette mesure restant appropriée face à un blocage qui, bien que gênant, ne présente pas de dimension violente.", "points": [{"position": 1, "label": "Traiter ces étudiants avec le respect dû à toute personne", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : mobilisation relevant d''une expression légitime.", "groups": [{"position": 1, "keywords": ["respect maintenu", "expression légitime", "mobilisation reconnue"]}]}, {"position": 2, "label": "Rechercher un dialogue pour envisager une résolution pacifique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Approche préférable à une confrontation directe.", "groups": [{"position": 1, "keywords": ["dialogue recherché", "résolution pacifique", "confrontation évitée"]}]}, {"position": 3, "label": "Rester factuelle sur les conséquences du blocage sans dénigrer la démarche", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Nécessité de rétablir l''accès sans jugement négatif.", "groups": [{"position": 1, "keywords": ["conséquences factuelles", "démarche non dénigrée", "accès à rétablir"]}]}, {"position": 4, "label": "Rester attentive à la proportionnalité de toute action envisagée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Mesure appropriée face à un blocage non violent.", "groups": [{"position": 1, "keywords": ["proportionnalité maintenue", "blocage non violent", "mesure appropriée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-rassemblement-hostile-envers-la-police', '{"slug": "ordre-rassemblement-hostile-envers-la-police", "title": "Une cinquantaine de personnes vous entoure après une interpellation", "theme_slug": "ordre-public", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 21 heures. Suite à une interpellation que vous venez d''effectuer dans un quartier, une cinquantaine de personnes se rassemble rapidement autour de votre équipage, cette foule manifestant une hostilité croissante à votre égard alors même que vous vous trouvez en position défavorable avec un effectif isolé et une personne interpellée qu''il vous faut impérativement protéger durant cette situation qui se dégrade rapidement. Cette configuration particulièrement dangereuse, où votre équipage se trouve numériquement très largement dépassé par cette foule hostile, nécessite une gestion prioritaire visant à vous dégager de cette position défavorable tout en assurant la protection de cette personne interpellée.\n\nCette situation, caractéristique des interventions où l''équipage se retrouve en position de vulnérabilité face à un rassemblement hostile grandissant, impose une action rapide de désengagement plutôt qu''une tentative de faire face frontalement à cette foule nombreuse et hostile.\n\nCette configuration nécessite de vous dégager de cette position tout en protégeant en priorité la personne interpellée, cette double exigence restant essentielle face à ce danger grandissant qui menace à la fois votre propre sécurité et celle de cette personne sous votre responsabilité.", "questions": [{"position": 1, "max_points": 5, "label": "Comment vous dégagez-vous de cette position défavorable face à cette foule hostile grandissante ?", "hint": "Ce dégagement doit être recherché activement plutôt qu''une confrontation frontale avec cette foule qui vous dépasse largement en nombre.", "perfect": "Je recherche activement une voie de dégagement pour quitter cette position défavorable, cette priorité restant essentielle face à ce déséquilibre numérique manifeste avec cette foule hostile.\n\nJe sollicite sans délai un renfort massif compte tenu de la gravité de cette situation, cette urgence absolue nécessitant une réponse rapide et proportionnée à ce danger.\n\nJe reste attentive à ne pas céder à la provocation de cette foule, cette maîtrise restant essentielle pour éviter toute escalade supplémentaire qui aggraverait davantage cette situation déjà critique.\n\nJe communique avec mon équipage pour coordonner ce dégagement de manière efficace, cette coordination restant nécessaire pour agir rapidement et de manière cohérente.", "points": [{"position": 1, "label": "Rechercher activement une voie de dégagement de cette position", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : priorité face au déséquilibre numérique.", "groups": [{"position": 1, "keywords": ["voie de dégagement", "position défavorable", "déséquilibre numérique"]}]}, {"position": 2, "label": "Solliciter sans délai un renfort massif", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Urgence absolue nécessitant une réponse rapide.", "groups": [{"position": 1, "keywords": ["renfort massif", "urgence absolue", "réponse rapide"]}]}, {"position": 3, "label": "Ne pas céder à la provocation de cette foule", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter toute escalade supplémentaire.", "groups": [{"position": 1, "keywords": ["pas de provocation", "escalade évitée", "situation critique"]}]}, {"position": 4, "label": "Communiquer avec l''équipage pour coordonner ce dégagement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Coordination nécessaire pour agir efficacement.", "groups": [{"position": 1, "keywords": ["coordination d''équipage", "dégagement efficace", "action cohérente"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment protégez-vous en priorité la personne interpellée durant cette situation dégradée ?", "hint": "Cette personne interpellée reste sous votre responsabilité directe et nécessite une protection prioritaire face à cette foule hostile, quelle que soit l''issue de son interpellation.", "perfect": "Je maintiens cette personne interpellée au plus près de moi et de mon équipage, cette proximité restant essentielle pour assurer sa protection physique face à cette foule potentiellement hostile envers elle également.\n\nJe reste attentive à ce que cette personne ne soit pas exposée directement à cette foule, cette vigilance restant nécessaire compte tenu du risque qu''elle pourrait courir dans cette situation tendue.\n\nJe reste consciente que cette protection reste ma responsabilité indépendamment des faits qui ont motivé cette interpellation, cette obligation de protection s''imposant quelle que soit la nature de cette procédure.\n\nJe communique clairement avec mon équipage sur cette priorité de protection, cette coordination restant essentielle pour assurer collectivement la sécurité de cette personne durant ce dégagement.", "points": [{"position": 1, "label": "Maintenir cette personne au plus près de l''équipage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : proximité assurant la protection physique.", "groups": [{"position": 1, "keywords": ["personne maintenue proche", "protection physique", "foule hostile"]}]}, {"position": 2, "label": "Rester attentive à ce qu''elle ne soit pas exposée directement à la foule", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Vigilance face au risque qu''elle pourrait courir.", "groups": [{"position": 1, "keywords": ["exposition évitée", "risque pour la personne", "vigilance nécessaire"]}]}, {"position": 3, "label": "Rester consciente que cette protection reste sa responsabilité indépendamment des faits", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Obligation s''imposant quelle que soit la procédure.", "groups": [{"position": 1, "keywords": ["responsabilité de protection", "indépendant des faits", "obligation constante"]}]}, {"position": 4, "label": "Communiquer clairement avec l''équipage sur cette priorité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Coordination pour la sécurité collective.", "groups": [{"position": 1, "keywords": ["priorité communiquée", "coordination d''équipage", "sécurité collective"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cette situation critique pour permettre une intervention adaptée ?", "hint": "Cette situation à haut risque nécessite un compte rendu précis et rapide pour permettre l''engagement des moyens appropriés face à ce danger immédiat.", "perfect": "Je transmets sans délai l''ampleur exacte de cette situation, notamment le nombre approximatif de personnes présentes et le niveau d''hostilité manifesté envers mon équipage.\n\nJe précise clairement ma position géographique exacte, cette information étant essentielle pour permettre un renfort rapide et efficace face à cette urgence absolue.\n\nJe signale la présence de cette personne interpellée et l''enjeu de sa protection, cette information complétant utilement l''appréciation de la gravité de cette situation par mes collègues.\n\nJe reste disponible pour toute information complémentaire, cette réactivité restant essentielle pour permettre une coordination optimale de l''intervention qui sera engagée.", "points": [{"position": 1, "label": "Transmettre l''ampleur exacte de la situation et le niveau d''hostilité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : nombre de personnes et hostilité manifestée.", "groups": [{"position": 1, "keywords": ["ampleur transmise", "hostilité signalée", "situation précisée"]}]}, {"position": 2, "label": "Préciser clairement sa position géographique exacte", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information essentielle pour un renfort rapide.", "groups": [{"position": 1, "keywords": ["position précisée", "renfort rapide", "urgence absolue"]}]}, {"position": 3, "label": "Signaler la présence de la personne interpellée et l''enjeu de sa protection", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information complétant l''appréciation de la gravité.", "groups": [{"position": 1, "keywords": ["personne signalée", "protection en jeu", "gravité appréciée"]}]}, {"position": 4, "label": "Rester disponible pour toute information complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour une coordination optimale.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "coordination optimale", "intervention engagée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-personne-malaise-dans-la-foule', '{"slug": "ordre-personne-malaise-dans-la-foule", "title": "Une femme s''effondre au milieu du cortège", "theme_slug": "ordre-public", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 16 heures. Lors d''une manifestation, une femme s''effondre soudainement au milieu du cortège en mouvement, cette urgence médicale survenant dans un environnement particulièrement saturé où la densité de la foule et la poursuite du mouvement de cette manifestation compliquent l''accès rapide des secours à cette personne qui nécessite une prise en charge immédiate. Cette situation, où un besoin de secours à personne s''impose au sein même d''un contexte de maintien de l''ordre, nécessite de créer rapidement un espace suffisant pour permettre l''intervention des services de secours sans pour autant chercher à interrompre l''ensemble du dispositif de cette manifestation.\n\nCette configuration, caractéristique de la nécessité de concilier une urgence médicale individuelle avec le contexte plus large d''un événement de maintien de l''ordre en cours, impose une action rapide et ciblée sur cet espace immédiat entourant cette personne en difficulté.\n\nCette situation nécessite de créer un espace pour les secours sans stopper l''ensemble du dispositif de cette manifestation, cette action ciblée restant la réponse appropriée à cette urgence médicale ponctuelle au sein de ce contexte plus large.", "questions": [{"position": 1, "max_points": 5, "label": "Comment créez-vous rapidement un espace pour permettre l''intervention des secours autour de cette femme ?", "hint": "Cet espace doit être créé rapidement malgré la densité de cette foule, cette action restant prioritaire pour permettre une prise en charge médicale immédiate.", "perfect": "Je me positionne rapidement autour de cette femme pour créer un périmètre de sécurité, cette action immédiate restant nécessaire pour permettre l''accès des secours dans cet environnement saturé.\n\nJe sollicite l''aide des manifestants les plus proches pour faciliter cette libération d''espace, cette coopération citoyenne pouvant utilement compléter mon action dans cette foule dense.\n\nJe demande sans délai l''intervention des services de secours compétents, cette urgence médicale nécessitant une prise en charge professionnelle rapide indépendamment de mes propres gestes de premier secours éventuels.\n\nJe reste attentive à maintenir cet espace dégagé jusqu''à l''arrivée effective de ces secours, cette vigilance restant nécessaire compte tenu de la pression que le mouvement de foule pourrait continuer à exercer.", "points": [{"position": 1, "label": "Se positionner rapidement pour créer un périmètre de sécurité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action immédiate dans un environnement saturé.", "groups": [{"position": 1, "keywords": ["périmètre créé", "action immédiate", "environnement saturé"]}]}, {"position": 2, "label": "Solliciter l''aide des manifestants proches pour libérer cet espace", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Coopération citoyenne complétant l''action.", "groups": [{"position": 1, "keywords": ["aide sollicitée", "coopération citoyenne", "espace libéré"]}]}, {"position": 3, "label": "Demander sans délai l''intervention des services de secours compétents", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prise en charge professionnelle rapide.", "groups": [{"position": 1, "keywords": ["secours demandés", "prise en charge professionnelle", "urgence médicale"]}]}, {"position": 4, "label": "Maintenir cet espace dégagé jusqu''à l''arrivée des secours", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance face à la pression de la foule.", "groups": [{"position": 1, "keywords": ["espace maintenu", "vigilance continue", "pression de la foule"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous cette urgence sans interrompre l''ensemble du dispositif de cette manifestation ?", "hint": "Cette action doit rester ciblée sur cette urgence médicale ponctuelle, sans pour autant chercher à arrêter l''intégralité du mouvement de cette manifestation en cours.", "perfect": "Je limite mon action à cet espace immédiat entourant cette personne, cette focalisation restant appropriée pour ne pas perturber inutilement l''ensemble du dispositif de cette manifestation.\n\nJe communique avec mes collègues présents sur cette situation ponctuelle, cette information permettant une gestion coordonnée sans nécessiter l''arrêt complet du cortège environnant.\n\nJe reste attentive à ce que le reste de la manifestation puisse continuer à se dérouler normalement autour de cette zone d''intervention ponctuelle, cette coexistence restant possible avec une gestion appropriée.\n\nJe reste concentrée sur cette urgence médicale sans me laisser distraire par le contexte plus large de cette manifestation en cours, cette priorité restant claire durant cette intervention ponctuelle.", "points": [{"position": 1, "label": "Limiter son action à cet espace immédiat entourant la personne", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : focalisation évitant de perturber le dispositif.", "groups": [{"position": 1, "keywords": ["action limitée", "espace immédiat", "dispositif préservé"]}]}, {"position": 2, "label": "Communiquer avec les collègues sur cette situation ponctuelle", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gestion coordonnée sans arrêt complet du cortège.", "groups": [{"position": 1, "keywords": ["collègues informés", "gestion coordonnée", "cortège maintenu"]}]}, {"position": 3, "label": "Permettre au reste de la manifestation de continuer normalement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Coexistence possible avec une gestion appropriée.", "groups": [{"position": 1, "keywords": ["manifestation continuée", "coexistence possible", "gestion appropriée"]}]}, {"position": 4, "label": "Rester concentrée sur cette urgence sans se laisser distraire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Priorité claire durant cette intervention ponctuelle.", "groups": [{"position": 1, "keywords": ["concentration maintenue", "priorité claire", "urgence prioritaire"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment accompagnez-vous cette femme et son entourage jusqu''à la prise en charge complète par les secours ?", "hint": "Cette femme et ses éventuels proches présents méritent un accompagnement rassurant durant cette attente, cette dimension humaine complétant la seule gestion technique de cette urgence.", "perfect": "Je reste présente auprès de cette femme durant l''attente des secours, cette présence pouvant la rassurer dans cette situation difficile qu''elle traverse au milieu de cette foule.\n\nJe recherche si des proches l''accompagnent dans ce cortège, ces personnes pouvant apporter des informations utiles sur son état de santé ou ses antécédents médicaux connus.\n\nJe reste attentive à son état durant cette attente, cette vigilance restant nécessaire pour signaler toute évolution aux services de secours dès leur arrivée sur place.\n\nJe transmets aux services de secours arrivants l''ensemble des informations recueillies durant cette attente, cette transmission facilitant leur prise en charge immédiate de cette situation.", "points": [{"position": 1, "label": "Rester présente auprès de cette femme durant l''attente des secours", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : présence rassurante dans cette situation difficile.", "groups": [{"position": 1, "keywords": ["présence maintenue", "rassurance apportée", "situation difficile"]}]}, {"position": 2, "label": "Rechercher si des proches l''accompagnent dans ce cortège", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Informations utiles sur son état ou ses antécédents.", "groups": [{"position": 1, "keywords": ["proches recherchés", "informations utiles", "antécédents médicaux"]}]}, {"position": 3, "label": "Rester attentive à son état durant cette attente", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance pour signaler toute évolution aux secours.", "groups": [{"position": 1, "keywords": ["état surveillé", "évolution signalée", "vigilance nécessaire"]}]}, {"position": 4, "label": "Transmettre les informations recueillies aux services de secours", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transmission facilitant la prise en charge immédiate.", "groups": [{"position": 1, "keywords": ["informations transmises", "prise en charge facilitée", "secours arrivants"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-drone-survolant-le-dispositif', '{"slug": "ordre-drone-survolant-le-dispositif", "title": "Un drone stationne au-dessus de la foule depuis vingt minutes", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 14 heures. Lors d''un rassemblement, vous constatez qu''un drone stationne immobile au-dessus de la foule depuis une vingtaine de minutes déjà, cette présence prolongée soulevant un risque réel de chute de cet appareil sur les personnes présentes en dessous, sans que l''opérateur de ce drone ne puisse être localisé parmi l''ensemble des personnes présentes sur ce site. Cette situation, qui combine un enjeu technologique inhabituel avec une véritable préoccupation de sécurité aérienne au-dessus d''une foule dense, nécessite une approche adaptée à cette configuration particulière qui sort du cadre habituel de vos interventions.\n\nCette configuration, où l''incertitude sur l''origine et les intentions de cet appareil s''ajoute au risque physique direct que sa chute éventuelle pourrait représenter, impose de rendre compte de cette situation tout en tentant de localiser cet opérateur sans pour autant intervenir directement sur cet appareil dont vous ne maîtrisez pas les caractéristiques techniques.\n\nCette situation nécessite de rendre compte de cette présence et de localiser l''opérateur sans agir directement sur cet appareil, cette prudence restant appropriée face à un enjeu technologique qui dépasse le cadre habituel de vos compétences et de vos moyens d''action directe.", "questions": [{"position": 1, "max_points": 5, "label": "Comment rendez-vous compte de cette situation particulière liée à la présence de ce drone ?", "hint": "Cette configuration technologique inhabituelle nécessite une remontée d''information précise pour permettre une appréciation appropriée de ce risque de sécurité aérienne.", "perfect": "Je transmets sans délai à ma hiérarchie la présence de ce drone stationnaire depuis une vingtaine de minutes, cette durée inhabituelle méritant une attention particulière compte tenu du risque de chute.\n\nJe précise avec exactitude la localisation de ce drone par rapport à la foule présente, cette information étant essentielle pour évaluer l''ampleur du risque que sa chute éventuelle pourrait représenter.\n\nJe reste attentive à décrire les caractéristiques observables de cet appareil, ces éléments techniques pouvant orienter utilement l''appréciation de la situation par les services compétents.\n\nJe reste disponible pour toute information complémentaire, cette réactivité restant importante face à cette configuration technologique qui sort du cadre habituel de mes interventions.", "points": [{"position": 1, "label": "Transmettre sans délai cette présence stationnaire inhabituelle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : durée méritant une attention particulière.", "groups": [{"position": 1, "keywords": ["présence transmise", "durée inhabituelle", "attention particulière"]}]}, {"position": 2, "label": "Préciser la localisation exacte du drone par rapport à la foule", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information essentielle pour évaluer le risque.", "groups": [{"position": 1, "keywords": ["localisation précisée", "risque évalué", "foule concernée"]}]}, {"position": 3, "label": "Décrire les caractéristiques observables de cet appareil", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éléments techniques orientant l''appréciation.", "groups": [{"position": 1, "keywords": ["caractéristiques décrites", "éléments techniques", "appréciation orientée"]}]}, {"position": 4, "label": "Rester disponible pour toute information complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité face à cette configuration inhabituelle.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "configuration inhabituelle", "réactivité importante"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment tentez-vous de localiser l''opérateur de ce drone sans agir directement sur cet appareil ?", "hint": "Cette recherche de l''opérateur reste utile pour comprendre les intentions de cette présence, cette démarche devant rester distincte de toute action directe sur ce drone lui-même.", "perfect": "Je recherche visuellement parmi les personnes présentes celles qui pourraient être en train de piloter cet appareil, cette observation restant le premier réflexe pour identifier cet opérateur.\n\nJe m''abstiens de toute action directe sur ce drone lui-même, cette réserve étant nécessaire compte tenu de mon absence de compétence technique et de moyens appropriés pour interagir avec cet appareil en vol.\n\nJe reste attentive aux zones d''où ce drone pourrait être piloté, notamment des points en hauteur ou en périphérie qui pourraient offrir une meilleure visibilité à cet opérateur.\n\nJe sollicite si possible la coopération des personnes présentes qui auraient pu observer l''origine de ce pilotage, ces témoignages pouvant compléter ma propre observation directe de la situation.", "points": [{"position": 1, "label": "Rechercher visuellement les personnes pouvant piloter cet appareil", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : premier réflexe d''identification.", "groups": [{"position": 1, "keywords": ["recherche visuelle", "opérateur identifié", "premier réflexe"]}]}, {"position": 2, "label": "S''abstenir de toute action directe sur ce drone lui-même", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réserve nécessaire compte tenu de l''absence de compétence technique.", "groups": [{"position": 1, "keywords": ["pas d''action directe", "compétence technique absente", "réserve nécessaire"]}]}, {"position": 3, "label": "Rester attentive aux zones offrant une meilleure visibilité à l''opérateur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Points en hauteur ou en périphérie.", "groups": [{"position": 1, "keywords": ["zones surveillées", "meilleure visibilité", "points en périphérie"]}]}, {"position": 4, "label": "Solliciter la coopération des personnes présentes ayant pu observer", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Témoignages complétant l''observation directe.", "groups": [{"position": 1, "keywords": ["coopération sollicitée", "témoignages recueillis", "observation complétée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous la sécurité de la foule en attendant une résolution de cette situation ?", "hint": "En attendant que cette situation soit résolue, une attention particulière à la sécurité immédiate des personnes présentes en dessous de ce drone reste nécessaire.", "perfect": "Je reste attentive à la zone directement exposée en dessous de ce drone, cette vigilance restant nécessaire compte tenu du risque de chute qui pourrait survenir à tout moment.\n\nJe reste attentive à toute évolution du comportement de cet appareil, notamment un mouvement soudain ou des signes de dysfonctionnement qui pourraient annoncer une chute imminente.\n\nJe reste disponible pour alerter rapidement les personnes présentes si ce risque venait à se matérialiser concrètement, cette réactivité restant essentielle pour la sécurité immédiate de la foule.\n\nJe reste consciente que cette situation, bien qu''inhabituelle, mérite un traitement sérieux compte tenu du danger physique réel qu''elle pourrait représenter pour les nombreuses personnes présentes.", "points": [{"position": 1, "label": "Rester attentive à la zone directement exposée sous ce drone", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vigilance face au risque de chute.", "groups": [{"position": 1, "keywords": ["zone exposée surveillée", "risque de chute", "vigilance constante"]}]}, {"position": 2, "label": "Rester attentive à toute évolution du comportement de l''appareil", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Signes de dysfonctionnement annonçant une chute imminente.", "groups": [{"position": 1, "keywords": ["comportement surveillé", "dysfonctionnement possible", "chute imminente"]}]}, {"position": 3, "label": "Rester disponible pour alerter rapidement si le risque se matérialise", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réactivité essentielle pour la sécurité immédiate.", "groups": [{"position": 1, "keywords": ["alerte rapide", "risque matérialisé", "sécurité immédiate"]}]}, {"position": 4, "label": "Reconnaître le sérieux de cette situation malgré son caractère inhabituel", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Danger physique réel pour les personnes présentes.", "groups": [{"position": 1, "keywords": ["situation sérieuse", "danger physique réel", "traitement approprié"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-marche-blanche-emotion-collective', '{"slug": "ordre-marche-blanche-emotion-collective", "title": "Six cents personnes en silence, la famille en tête", "theme_slug": "ordre-public", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 18 heures. Vous encadrez une marche blanche réunissant environ six cents personnes qui progressent en silence dans le centre-ville, la famille endeuillée à l''origine de ce rassemblement se trouvant en tête de ce cortège empreint d''une émotion collective palpable et particulièrement digne. Cette configuration, radicalement différente des manifestations plus habituelles nécessitant un encadrement plus visible et parfois plus ferme, impose une présence policière qui se dose avec un tact particulier pour respecter pleinement cette émotion partagée sans pour autant renoncer à la sécurisation nécessaire de ce rassemblement.\n\nCette situation, où la discrétion de votre dispositif doit primer sur toute autre considération habituelle de maintien de l''ordre, nécessite une présence qui accompagne sans jamais paraître s''imposer face à cette communion silencieuse et recueillie de l''ensemble de ces participants.\n\nCette configuration impose de faire preuve de discrétion dans votre dispositif tout en respectant pleinement cette émotion collective, cette double exigence restant essentielle pour accompagner dignement cette marche sans jamais en perturber le caractère solennel et recueilli.", "questions": [{"position": 1, "max_points": 5, "label": "Comment adaptez-vous votre dispositif pour qu''il reste discret face à cette émotion collective ?", "hint": "Cette discrétion du dispositif doit primer sur les habitudes plus visibles de maintien de l''ordre, cette adaptation restant essentielle pour respecter le caractère recueilli de cette marche.", "perfect": "Je positionne mon dispositif de manière à assurer la sécurisation nécessaire sans pour autant paraître envahissant, cette discrétion restant essentielle face au caractère recueilli de cette marche.\n\nJe reste attentive à mon propre comportement et à mon attitude durant cet accompagnement, cette sobriété restant appropriée pour respecter l''émotion palpable de l''ensemble de ces participants.\n\nJe communique si nécessaire avec mes collègues sur cette nécessité de discrétion collective, cette cohésion d''attitude restant importante pour l''ensemble du dispositif accompagnant cette marche.\n\nJe reste consciente que ma seule présence, aussi discrète soit-elle, reste nécessaire pour assurer la sécurité de ce rassemblement dans cet espace public traversé par ce cortège.", "points": [{"position": 1, "label": "Positionner le dispositif pour assurer la sécurisation sans paraître envahissant", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : discrétion face au caractère recueilli.", "groups": [{"position": 1, "keywords": ["dispositif discret", "sécurisation assurée", "caractère recueilli"]}]}, {"position": 2, "label": "Rester attentive à son propre comportement et attitude sobre", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sobriété respectant l''émotion palpable.", "groups": [{"position": 1, "keywords": ["comportement sobre", "attitude appropriée", "émotion respectée"]}]}, {"position": 3, "label": "Communiquer avec les collègues sur cette nécessité de discrétion collective", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Cohésion d''attitude importante pour l''ensemble du dispositif.", "groups": [{"position": 1, "keywords": ["discrétion communiquée", "cohésion collective", "dispositif uniforme"]}]}, {"position": 4, "label": "Rester consciente de la nécessité de sa présence malgré la discrétion", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sécurité assurée dans l''espace public traversé.", "groups": [{"position": 1, "keywords": ["présence nécessaire", "sécurité assurée", "espace public"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment respectez-vous pleinement cette émotion collective tout en assurant vos responsabilités de sécurisation ?", "hint": "Ce respect de l''émotion collective ne doit pas conduire à renoncer aux responsabilités essentielles de sécurisation de ce rassemblement dans l''espace public.", "perfect": "Je reste attentive à ne jamais interrompre inutilement le silence et le recueillement de ce cortège, cette retenue restant essentielle pour respecter cette communion collective.\n\nJe maintiens néanmoins ma vigilance sur la sécurisation de ce parcours, notamment la gestion de la circulation et des éventuels risques liés à cet espace public traversé par cette marche.\n\nJe reste attentive à la famille endeuillée en tête de ce cortège, cette proximité méritant une attention particulière et respectueuse compte tenu de son rôle central dans ce rassemblement.\n\nJe reste disponible pour intervenir si nécessaire tout en restant en retrait, cette disponibilité discrète permettant de concilier ma responsabilité de sécurisation avec le respect de cette émotion collective.", "points": [{"position": 1, "label": "Ne jamais interrompre inutilement le silence et le recueillement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : retenue respectant la communion collective.", "groups": [{"position": 1, "keywords": ["silence respecté", "recueillement préservé", "communion collective"]}]}, {"position": 2, "label": "Maintenir la vigilance sur la sécurisation du parcours", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Circulation et risques liés à l''espace public.", "groups": [{"position": 1, "keywords": ["vigilance maintenue", "circulation gérée", "risques surveillés"]}]}, {"position": 3, "label": "Rester attentive à la famille endeuillée avec une attention respectueuse", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rôle central de la famille dans ce rassemblement.", "groups": [{"position": 1, "keywords": ["famille endeuillée", "attention respectueuse", "rôle central"]}]}, {"position": 4, "label": "Rester disponible pour intervenir tout en restant en retrait", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité discrète conciliant sécurisation et respect.", "groups": [{"position": 1, "keywords": ["disponibilité discrète", "intervention possible", "retrait maintenu"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous d''éventuelles interactions avec les participants durant cette marche silencieuse ?", "hint": "Ces interactions, si elles s''avèrent nécessaires, doivent rester exceptionnelles et respectueuses du caractère silencieux et recueilli de ce rassemblement particulier.", "perfect": "Je limite mes interactions verbales au strict nécessaire, cette sobriété restant appropriée pour ne pas perturber le silence recueilli de l''ensemble de ces participants.\n\nJe privilégie, si une communication s''avère nécessaire, des gestes discrets plutôt que des paroles qui pourraient rompre inopportunément ce silence collectif.\n\nJe reste attentive et bienveillante si des participants venaient à s''adresser à moi durant cette marche, cette disponibilité restant appropriée sans pour autant que j''initie moi-même des échanges non essentiels.\n\nJe reste consciente que mon comportement durant cette marche pourra être perçu par l''ensemble de ces participants, cette conscience m''incitant à une exemplarité particulière dans ce contexte solennel.", "points": [{"position": 1, "label": "Limiter les interactions verbales au strict nécessaire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : sobriété ne perturbant pas le silence recueilli.", "groups": [{"position": 1, "keywords": ["interactions limitées", "sobriété maintenue", "silence recueilli"]}]}, {"position": 2, "label": "Privilégier des gestes discrets plutôt que des paroles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas rompre inopportunément le silence collectif.", "groups": [{"position": 1, "keywords": ["gestes discrets", "paroles évitées", "silence préservé"]}]}, {"position": 3, "label": "Rester attentive et bienveillante sans initier d''échanges non essentiels", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Disponibilité sans initiative superflue.", "groups": [{"position": 1, "keywords": ["bienveillance maintenue", "pas d''initiative superflue", "disponibilité appropriée"]}]}, {"position": 4, "label": "Rester consciente de l''exemplarité attendue dans ce contexte solennel", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Comportement perçu par l''ensemble des participants.", "groups": [{"position": 1, "keywords": ["exemplarité attendue", "comportement perçu", "contexte solennel"]}]}]}]}'::jsonb);